program='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen0 = set()
    zero_regions = []
    # Partition zero cells into 4-connected regions; regions away from the edge are enclosed.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen0:
                continue
            q = deque([(r, c)])
            seen0.add((r, c))
            region = []
            touches_edge = False
            while q:
                y, x = q.popleft()
                region.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and (ny,nx) not in seen0:
                        seen0.add((ny,nx)); q.append((ny,nx))
            zero_regions.append((region, not touches_edge))

    # Find each 4-connected component of the 1-line. Components enclosing any zero region
    # receive a 2-colored outer edge and a 3-colored inner edge.
    seen1 = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r,c) in seen1:
                continue
            q = deque([(r,c)]); seen1.add((r,c)); comp=[]
            while q:
                y,x=q.popleft(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]==1 and (ny,nx) not in seen1:
                        seen1.add((ny,nx)); q.append((ny,nx))
            adjacent = {}
            for region, enclosed in zero_regions:
                for y,x in region:
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and grid[ny][nx]==1 and (ny,nx) in comp:
                            adjacent[(y,x)] = enclosed
            if any(adjacent.values()):
                for (y,x), enclosed in adjacent.items():
                    out[y][x] = 3 if enclosed else 2
    return out
'''
